#!/usr/bin/env perl
use strict;
use warnings;
use File::Path qw(make_path);

my $root = '/workspace';
my $final = "$root/final_answer";
my $metadata_dir = "$final/metadata";
my $reads_dir = "$final/reads";
make_path($metadata_dir, $reads_dir);

my @projects = qw(PRJNA1354216 PRJNA1339024);

sub parse_csv_line {
    my ($line) = @_;
    chomp $line;
    $line =~ s/\r\z//;
    my @fields;
    my $field = '';
    my $quoted = 0;
    my @chars = split //, $line;
    for (my $i = 0; $i < @chars; $i++) {
        my $c = $chars[$i];
        if ($quoted) {
            if ($c eq '"') {
                if ($i + 1 < @chars && $chars[$i + 1] eq '"') {
                    $field .= '"';
                    $i++;
                } else {
                    $quoted = 0;
                }
            } else {
                $field .= $c;
            }
        } elsif ($c eq '"' && $field eq '') {
            $quoted = 1;
        } elsif ($c eq ',') {
            push @fields, $field;
            $field = '';
        } else {
            $field .= $c;
        }
    }
    die "Unclosed CSV quote\n" if $quoted;
    push @fields, $field;
    return \@fields;
}

sub read_csv_table {
    my ($path) = @_;
    open my $fh, '<:raw', $path or die "Cannot read $path: $!\n";
    my $header_line = <$fh>;
    die "Missing CSV header in $path\n" unless defined $header_line;
    my $header = parse_csv_line($header_line);
    my %idx;
    for my $i (0 .. $#$header) {
        die "Duplicate CSV header $header->[$i] in $path\n" if exists $idx{$header->[$i]};
        $idx{$header->[$i]} = $i;
    }
    my @rows;
    while (my $line = <$fh>) {
        next if $line =~ /^\s*\z/;
        my $row = parse_csv_line($line);
        die "Wrong CSV field count in $path: got " . scalar(@$row) . " expected " . scalar(@$header) . "\n"
            unless @$row == @$header;
        my %record;
        @record{@$header} = @$row;
        push @rows, \%record;
    }
    close $fh or die "Cannot close $path: $!\n";
    return \@rows;
}

sub read_tsv_table {
    my ($path) = @_;
    open my $fh, '<:raw', $path or die "Cannot read $path: $!\n";
    my $header_line = <$fh>;
    die "Missing TSV header in $path\n" unless defined $header_line;
    chomp $header_line;
    $header_line =~ s/\r\z//;
    my @header = split /\t/, $header_line, -1;
    my %idx;
    for my $i (0 .. $#header) {
        die "Duplicate TSV header $header[$i] in $path\n" if exists $idx{$header[$i]};
        $idx{$header[$i]} = $i;
    }
    my @rows;
    while (my $line = <$fh>) {
        chomp $line;
        $line =~ s/\r\z//;
        next if $line eq '';
        my @values = split /\t/, $line, -1;
        die "Wrong TSV field count in $path\n" unless @values == @header;
        my %record;
        @record{@header} = @values;
        push @rows, \%record;
    }
    close $fh or die "Cannot close $path: $!\n";
    return \@rows;
}

my %run_by_accession;
my %runs_by_project;
for my $bp (@projects) {
    my $path = "/tmp/${bp}.runinfo.csv";
    my $rows = read_csv_table($path);
    die "$bp has no public SRA runs\n" unless @$rows;
    for my $r (@$rows) {
        die "BioProject mismatch for $r->{Run}: $r->{BioProject} != $bp\n"
            unless $r->{BioProject} eq $bp;
        die "Missing run accession for $bp\n" unless $r->{Run};
        die "Duplicate run accession $r->{Run}\n" if exists $run_by_accession{$r->{Run}};
        die "Unexpected layout for $r->{Run}: $r->{LibraryLayout}\n"
            unless $r->{LibraryLayout} eq 'SINGLE' || $r->{LibraryLayout} eq 'PAIRED';
        $r->{_bioproject} = $bp;
        $run_by_accession{$r->{Run}} = $r;
        push @{ $runs_by_project{$bp} }, $r;
    }
}

my %ena_by_run;
for my $report (qw(/tmp/SRP637459.ena.tsv /tmp/SRP630949.ena.tsv)) {
    my $rows = read_tsv_table($report);
    for my $r (@$rows) {
        die "Duplicate ENA run accession $r->{run_accession}\n" if exists $ena_by_run{$r->{run_accession}};
        $ena_by_run{$r->{run_accession}} = $r;
    }
}

my @metadata_header = qw(
    bioproject run_accession study_accession experiment_accession sample_accession biosample
    organism_taxid organism_name library_strategy library_source library_selection library_layout
    instrument_model run_total_spots run_total_bases release_date load_date spots_with_mates
    average_read_length size_mb sra_download_path library_name platform sample_type sample_name
    center_name submission consent run_hash read_hash
);

sub tsv_value {
    my ($value, $label) = @_;
    $value = '' unless defined $value;
    die "TSV value for $label contains a tab or newline\n" if $value =~ /[\t\r\n]/;
    return $value;
}

for my $bp (@projects) {
    my @rows = sort { $a->{Run} cmp $b->{Run} } @{ $runs_by_project{$bp} };
    my $path = "$metadata_dir/${bp}.tsv";
    open my $out, '>:raw', $path or die "Cannot write $path: $!\n";
    print {$out} join("\t", @metadata_header), "\n";
    for my $r (@rows) {
        my @values = (
            $bp,
            $r->{Run},
            $r->{SRAStudy},
            $r->{Experiment},
            $r->{Sample},
            $r->{BioSample},
            $r->{TaxID},
            $r->{ScientificName},
            $r->{LibraryStrategy},
            $r->{LibrarySource},
            $r->{LibrarySelection},
            $r->{LibraryLayout},
            $r->{Model},
            $r->{spots},
            $r->{bases},
            $r->{ReleaseDate},
            $r->{LoadDate},
            $r->{spots_with_mates},
            $r->{avgLength},
            $r->{size_MB},
            $r->{download_path},
            $r->{LibraryName},
            $r->{Platform},
            $r->{SampleType},
            $r->{SampleName},
            $r->{CenterName},
            $r->{Submission},
            $r->{Consent},
            $r->{RunHash},
            $r->{ReadHash},
        );
        @values = map { tsv_value($_, $r->{Run}) } @values;
        print {$out} join("\t", @values), "\n";
    }
    close $out or die "Cannot close $path: $!\n";
}

open my $catalog, '>:raw', "$root/work/run_catalog.tsv" or die "Cannot write run catalog: $!\n";
print {$catalog} join("\t", qw(bioproject run_accession library_layout run_total_spots run_total_bases forward_url reverse_url forward_md5 reverse_md5 forward_bytes reverse_bytes)), "\n";
for my $run (sort keys %run_by_accession) {
    my $r = $run_by_accession{$run};
    my $e = $ena_by_run{$run} or die "No ENA FASTQ report for $run\n";
    my @urls = split /;/, ($e->{fastq_ftp} // ''), -1;
    my @md5s = split /;/, ($e->{fastq_md5} // ''), -1;
    my @bytes = split /;/, ($e->{fastq_bytes} // ''), -1;
    my $expected = $r->{LibraryLayout} eq 'PAIRED' ? 2 : 1;
    die "Wrong number of ENA FASTQs for $run: got " . scalar(@urls) . " expected $expected\n"
        unless @urls == $expected && @md5s == $expected && @bytes == $expected;
    die "Empty ENA FASTQ URL for $run\n" if grep { $_ eq '' } @urls;
    my @full_urls = map { /^https?:\/\// ? $_ : "https://$_" } @urls;
    print {$catalog} join("\t", map { tsv_value($_, $run) } (
        $r->{_bioproject}, $run, $r->{LibraryLayout}, $r->{spots}, $r->{bases},
        $full_urls[0], ($full_urls[1] // ''), $md5s[0], ($md5s[1] // ''), $bytes[0], ($bytes[1] // ''),
    )), "\n";
}
close $catalog or die "Cannot close run catalog: $!\n";

print "Wrote metadata tables for ", scalar(@projects), " BioProjects and cataloged ", scalar(keys %run_by_accession), " runs.\n";
